{"content": "#!/usr/bin/env python3
"""Block-level TileLang design for LayerNorm.

LayerNorm: y = (x - mean) / sqrt(var + eps) * weight + bias

The scheduling evolves with hidden size N (product of normalized_shape):
- `merge_n` for small N (<= 1024): UB can hold multiple full rows,
  process several rows together for vector efficiency.
- `single_row` for medium N (1024 < N <= 8192): full row fits in UB,
  but only one row at a time.
- `splitd` for large N (> 8192): even one full row does not fit in UB,
  split along the hidden dimension, process in two passes.

Block-level decomposition:
- Input x is reshaped to [M, N] where N = prod(normalized_shape)
- M rows are distributed across cores by block_m chunks (block_m = 64)
- Each core processes tasks_per_core blocks
- Within each block, vec_num=2 vector units process sub_block_m rows
- No inter-core communication required (each row is independent)
"""

import tilelang
import tilelang.language as T

pass_configs = {
    tilelang.PassConfigKey.TL_ASCEND_AUTO_SYNC: True,
    tilelang.PassConfigKey.TL_ASCEND_MEMORY_PLANNING: True,
}


@tilelang.jit(out_idx=[2], pass_configs=pass_configs)
def layer_norm(m_size, n_size, eps=1e-5, dtype="float32"):
    block_m = 64
    block_n = 1024
    num_physical_cores = 20
    if m_size % block_m != 0:
        raise ValueError(f"M={m_size} must be divisible by block_M={block_m}")
    m_num = m_size // block_m
    if m_num <= 0:
        raise ValueError(f"m_num must be positive, got {m_num}")
    used_core_num = min(num_physical_cores, m_num)
    tasks_per_core = (m_num + used_core_num - 1) // used_core_num
    vec_num = 2
    sub_block_m = block_m // vec_num

    row_factor = 8
    row_loops = sub_block_m // row_factor
    n_num = (n_size + block_n - 1) // block_n

    @T.prim_func
    def merge_n(
        x_in: T.Tensor((m_size, n_size), dtype),
        gamma: T.Tensor((n_size,), dtype),
        beta: T.Tensor((n_size,), dtype),
        y_out: T.Tensor((m_size, n_size), dtype),
    ):
        with T.Kernel(used_core_num, is_npu=True) as (cid, vid):
            core_idx = cid

            def _process_rows_for_bx(bx, vid):
                for r in T.serial(row_loops):
                    row_base = bx * block_m + vid * sub_block_m + r * row_factor
                    _ = (x_in, gamma, beta, y_out, row_base)
                    # TODO(tile-level): compute mean, var, normalize row_factor rows

            def _process_bx(bx, vid):
                with T.Scope("V"):
                    if bx < m_num:
                        _process_rows_for_bx(bx, vid)

            for local_idx in T.serial(tasks_per_core):
                bx = core_idx * tasks_per_core + local_idx
                _process_bx(bx, vid)

    @T.prim_func
    def single_row(
        x_in: T.Tensor((m_size, n_size), dtype),
        gamma: T.Tensor((n_size,), dtype),
        beta: T.Tensor((n_size,), dtype),
        y_out: T.Tensor((m_size, n_size), dtype),
    ):
        with T.Kernel(used_core_num, is_npu=True) as (cid, vid):
            core_idx = cid

            def _process_rows_for_bx(bx, vid):
                for row in T.serial(sub_block_m):
                    row_idx = bx * block_m + vid * sub_block_m + row
                    _ = (x_in, gamma, beta, y_out, row_idx)
                    # TODO(tile-level): compute mean, var, normalize single row

            def _process_bx(bx, vid):
                with T.Scope("V"):
                    if bx < m_num:
                        _process_rows_for_bx(bx, vid)

            for local_idx in T.serial(tasks_per_core):
                bx = core_idx * tasks_per_core + local_idx
                _process_bx(bx, vid)

    @T.prim_func
    def splitd(
        x_in: T.Tensor((m_size, n_size), dtype),
        gamma: T.Tensor((n_size,), dtype),
        beta: T.Tensor((n_size,), dtype),
        y_out: T.Tensor((m_size, n_size), dtype),
    ):
        with T.Kernel(used_core_num, is_npu=True) as (cid, vid):
            core_idx = cid

            def _process_rows_for_bx(bx, vid):
                for row in T.serial(sub_block_m):
                    row_idx = bx * block_m + vid * sub_block_m + row
                    _ = (x_in, gamma, beta, y_out, row_idx, n_num)
                    # TODO(tile-level): two-pass: pass1 compute sum & sumsq, pass2 normalize

            def _process_bx(bx, vid):
                with T.Scope("V"):
                    if bx < m_num:
                        _process_rows_for_bx(bx, vid)

            for local_idx in T.serial(tasks_per_core):
                bx = core_idx * tasks_per_core + local_idx
                _process_bx(bx, vid)

    _ = eps

    if n_size <= 1024:
        return merge_n
    if n_size > 8192:
        return splitd
    return single_row
