{"content": "#!/usr/bin/env python3

import math
import sys
from pathlib import Path

import torch
import torch.nn as nn

_TASK_DIR = Path(__file__).resolve().parent
if str(_TASK_DIR) not in sys.path:
    sys.path.insert(0, str(_TASK_DIR))

from design.tile_level.layer_norm import layer_norm as tl_layer_norm


class ModelNew(nn.Module):
    def __init__(self, eps: float = 1e-5) -> None:
        super().__init__()
        self.eps = eps

    def forward(
        self,
        x: torch.Tensor,
        normalized_shape: list,
        weight: torch.Tensor = None,
        bias: torch.Tensor = None,
    ) -> torch.Tensor:
        if x.dtype not in (torch.float16, torch.float32, torch.bfloat16):
            raise ValueError(f"Unsupported dtype {x.dtype}")

        original_shape = x.shape
        ndim_norm = len(normalized_shape)

        # Determine N = product of normalized_shape dimensions
        n_size = 1
        for ns in normalized_shape:
            n_size *= ns

        # Reshape x to [M, N]
        m_size = x.numel() // n_size
        x_2d = x.reshape(m_size, n_size).contiguous()

        # Prepare weight and bias (create ones/zeros if not provided)
        if weight is not None:
            weight_1d = weight.reshape(-1).contiguous()
            if weight_1d.shape[0] != n_size:
                raise ValueError(
                    f"weight size {weight_1d.shape[0]} != normalized_shape product {n_size}"
                )
        else:
            weight_1d = torch.ones(n_size, dtype=x.dtype, device=x.device)

        if bias is not None:
            bias_1d = bias.reshape(-1).contiguous()
            if bias_1d.shape[0] != n_size:
                raise ValueError(
                    f"bias size {bias_1d.shape[0]} != normalized_shape product {n_size}"
                )
        else:
            bias_1d = torch.zeros(n_size, dtype=x.dtype, device=x.device)

        # Build and invoke the kernel
        kernel = self._build_kernel(x_2d)
        y_2d = kernel(x_2d, weight_1d, bias_1d)

        # Reshape output back to original shape
        return y_2d.reshape(original_shape)

    def _build_kernel(self, x: torch.Tensor):
        m, n = x.shape
        return tl_layer_norm(
            m,
            n,
            eps=self.eps,
            dtype=str(x.dtype).split(".")[-1],
        )
