// LayerNorm op_host — tiling calculation + strategy dispatch + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <ATen/ATen.h>
#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_layer_norm_merge_n.h"
#include "aclrtlaunch_layer_norm_single_row.h"
#include "aclrtlaunch_layer_norm_splitd.h"

// ---------------------------------------------------------------------------
// Tiling constants
// ---------------------------------------------------------------------------

constexpr int32_t DEFAULT_BLOCK_M = 64;
constexpr int32_t DEFAULT_ROW_FACTOR = 8;
constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

// ---------------------------------------------------------------------------
// Host function
// ---------------------------------------------------------------------------

namespace ascend_kernel {

at::Tensor layer_norm(
    const at::Tensor &x,
    at::IntArrayRef normalized_shape,
    const c10::optional<at::Tensor> &weight,
    const c10::optional<at::Tensor> &bias,
    double eps)
{
    TORCH_CHECK(x.scalar_type() == at::kFloat || x.scalar_type() == at::kHalf ||
                    x.scalar_type() == at::kBFloat16,
                "x must be float16, float32, or bfloat16");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // Calculate N = product of normalized_shape
    int64_t nSize = 1;
    for (int64_t s : normalized_shape) {
        nSize *= s;
    }

    // Reshape x to [M, N]
    int64_t mSize = x.numel() / nSize;
    at::Tensor x_2d = x.reshape({mSize, nSize}).contiguous();
    auto dtype = x.scalar_type();

    // Handle optional weight
    at::Tensor weight_1d;
    if (weight.has_value()) {
        weight_1d = weight->reshape(-1).contiguous();
    } else {
        weight_1d = at::ones({nSize}, x.options());
    }

    // Handle optional bias
    at::Tensor bias_1d;
    if (bias.has_value()) {
        bias_1d = bias->reshape(-1).contiguous();
    } else {
        bias_1d = at::zeros({nSize}, x.options());
    }

    TORCH_CHECK(weight_1d.scalar_type() == x_2d.scalar_type(),
                "weight must have the same dtype as x");
    TORCH_CHECK(bias_1d.scalar_type() == x_2d.scalar_type(),
                "bias must have the same dtype as x");
    TORCH_CHECK(weight_1d.size(0) == nSize,
                "weight size mismatch with normalized_shape product");
    TORCH_CHECK(bias_1d.size(0) == nSize,
                "bias size mismatch with normalized_shape product");

    int32_t M = static_cast<int32_t>(mSize);
    int32_t N = static_cast<int32_t>(nSize);

    int32_t mNum = (M + DEFAULT_BLOCK_M - 1) / DEFAULT_BLOCK_M;
    int32_t usedCoreNum = std::min<int32_t>(DEFAULT_NUM_PHYSICAL_CORES,
                                             std::max<int32_t>(1, mNum));
    int32_t tasksPerCore = (mNum + usedCoreNum - 1) / usedCoreNum;

    at::Tensor yOut_2d = at::empty_like(x_2d);

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (dtype == at::kHalf) {
        dtypeFlag = 1;
    } else if (dtype == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // All tiling params as left values (required by EXEC_KERNEL_CMD)
    int32_t blockM = DEFAULT_BLOCK_M;
    int32_t rowFactor = DEFAULT_ROW_FACTOR;
    float epsVal = static_cast<float>(eps);
    float invN = 1.0f / static_cast<float>(N);
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // Strategy dispatch: select kernel name and params
    if (N <= 1024) {
        EXEC_KERNEL_CMD(layer_norm_merge_n, blockDim,
                        x_2d, weight_1d, bias_1d, yOut_2d,
                        M, N, blockM, usedCoreNum, tasksPerCore, rowFactor, epsVal, invN,
                        dtypeFlag);
    } else if (N > 8192) {
        EXEC_KERNEL_CMD(layer_norm_splitd, blockDim,
                        x_2d, weight_1d, bias_1d, yOut_2d,
                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
                        dtypeFlag);
    } else {
        EXEC_KERNEL_CMD(layer_norm_single_row, blockDim,
                        x_2d, weight_1d, bias_1d, yOut_2d,
                        M, N, blockM, usedCoreNum, tasksPerCore, epsVal, invN,
                        dtypeFlag);
    }

    return yOut_2d.reshape(x.sizes());
}

}  // namespace ascend_kernel
