// =========================================================================
// Shared dtype-dispatch helper
// =========================================================================

template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchLayerNorm(
    GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
    int32_t M, int32_t N, int32_t blockM, int32_t usedCoreNum,
    int32_t tasksPerCore, float eps, float invN,
    int64_t dtypeFlag, ExtraArgs... extraArgs)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(x, gamma, beta, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(x, gamma, beta, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(x, gamma, beta, y, M, N, blockM, usedCoreNum, tasksPerCore, extraArgs..., eps, invN);
        kernel.Process();
    }
}

